function validate(input) {
  const [{ Candidates = [] }] = input;
  const seen = new Set();
  for (const [id, skill] of Candidates) {
    if (id === null || skill === null) return 'candidate_id and skill are required.';
    const key = `${id}|${String(skill).toLowerCase()}`;
    if (seen.has(key)) return `Candidate ${id} lists ${skill} twice.`;
    seen.add(key);
  }
  return null;
}

