function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const required = ['Python', 'Tableau', 'PostgreSQL'];
  const others = ['R', 'Java', 'PowerBI', 'SQL Server', 'DataAnalysis', 'Excel'];
  const Candidates = [];
  if (size === 'small') {
    // A handful of candidates, each holding a random mix that is often one required skill short.
    const ids = [102, 123, 147, 234, 256];
    let budget = pick(9);
    for (const id of ids) {
      const skills = required.filter(() => rand() < 0.75).concat(others.filter(() => rand() < 0.15));
      for (const skill of skills) {
        if (budget === 0) break;
        Candidates.push([id, skill]);
        budget--;
      }
    }
    // Shuffle so the input is not already sorted by candidate.
    for (let i = Candidates.length - 1; i > 0; i--) { const j = pick(i + 1); [Candidates[i], Candidates[j]] = [Candidates[j], Candidates[i]]; }
  } else {
    // About 450 candidates with ids out of order; roughly 40% hold all three required skills.
    for (let k = 0; k < 450; k++) {
      const id = 1000 + ((k * 7919) % 4500);
      for (const skill of required) if (rand() < 0.75) Candidates.push([id, skill]);
      for (const skill of others) if (rand() < 0.2) Candidates.push([id, skill]);
    }
  }
  return [{ Candidates }];
}
